def is_symmetric(root: list) -> bool:
    node = _build(root)

    def mirror(a, b) -> bool:
        if a is None or b is None:
            return a is b
        return a.value == b.value and mirror(a.left, b.right) and mirror(a.right, b.left)

    return node is None or mirror(node.left, node.right)

